import{z as s,x as o,o as A,c as d,q as r,j as t,D as e,d as E,s as n,S as i,b as B}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"红队工程：自动化与人工","description":"","frontmatter":{"title":"红队工程：自动化与人工","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/aeval-redteam-engineering.md","filePath":"llm/aeval-redteam-engineering.md","lastUpdated":1791063341000}'),D={name:"llm/aeval-redteam-engineering.md"};function m(p,a,h,g,f,u){const l=o("Mermaid");return A(),d("div",null,[a[2]||(a[2]=r('<h1 id="红队工程-自动化与人工" tabindex="-1">红队工程：自动化与人工 <a class="header-anchor" href="#红队工程-自动化与人工" aria-label="Permalink to &quot;红队工程：自动化与人工&quot;">​</a></h1><div class="epigraph"><p>红队不是找一颗子弹，而是描绘一片弹着点：单条攻击会过时，失败在政策类别与攻击族上的分布才是资产。</p><footer>—— 据 Ganguli et al., Red Teaming Language Models with Language Models, 2022 整理</footer></div><p><a href="/llm/aeval-safety-benchmark-design">上一课</a>把安全基准钉成政策先行、成对构造、版本绑定的静态仪器。静态套件只能测已知失败；红队是主动生产失败的过程，它的产出反过来喂饱和的基准。主干已有<a href="/llm/red-team-eval">红队评测</a>与<a href="/llm/jailbreak">越狱评测</a>的框架位；本课写工程：自动化与人工两条产线怎么分工，一条发现怎么走完漏斗变成可版本化的回归资产。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><span class="marginnote">术语翻译：红队（red team）借自军事演习——己方专门抽一组人扮演敌人，来攻自己的防线。对模型而言，就是有人（或另一个模型）专职扮演攻击者去「越狱」、套有害输出；注意红队找不到漏洞不等于没有漏洞，只代表这支队伍这轮预算下没找到。</span>两条产线各有失败模式。自动化产线便宜、可放量：模型当攻击者批量生成变体，优化后缀类攻击能压到很高配合率（见<a href="/llm/gcg-suffix">对抗鲁棒评测</a>的谱系位）。但同一生成器分布里的攻击高度同质——它只在它见过的邻域里找失败，产出几百条模板变体，覆盖的可能是同一类漏洞，这是广度的错觉。人工产线给得出域深度与真正的分布外攻击：多语言混写、专业域包装、多步脚本，但贵、慢、不可复现，发现常躺在聊天记录与工单里，人一走就丢。缺口是工程化的漏斗：把「发现」从故事变成数据，让两条产线的产出可比、可去重、可回归。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="漏斗的五段" tabindex="-1">漏斗的五段 <a class="header-anchor" href="#漏斗的五段" aria-label="Permalink to &quot;漏斗的五段&quot;">​</a></h3><p>范围先行：政策版本与接口清单（是否暴露补全、工具、多模态）先冻结，否则无法判定一条输出算不算失败。然后双产线并行。<strong>自动产线</strong>：模板变异、模型生成攻击、公开实现的优化攻击按黑盒调用；<strong>人工产线</strong>：域专家与众包按 Ganguli et al. 2022 的规模化口径组织，任务设计给足上下文与激励。两线产出进同一条漏斗：去重聚类 → 政策映射 → 有效失败判定 → 私有回归集 → 修复后复测。有效失败三个条件缺一不可：政策违反、可复现（固定解码能重现）、判分一致（裁判与人判同向）。不可复现的没法进门禁；判分不一致的会制造假警报，耗尽工程带宽。<span class="marginnote">为什么重要：三条件里「判分一致」最易被忽略。对抗输出常带误导性说辞，裁判判成「无危害」而人判成「有害」，这条攻击就会在每轮复测里反复触发假警报——工程带宽被耗在追查幽灵失败上，真正的漏洞反而排不上队。</span></p>',8)),(A(),t(i,null,{default:e(()=>[n(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SCOPE%5B%22%E8%8C%83%E5%9B%B4%EF%BC%9A%E6%94%BF%E7%AD%96%E7%89%88%E6%9C%AC%20%2B%20%E6%8E%A5%E5%8F%A3%E6%B8%85%E5%8D%95%22%5D%20--%3E%20AUTO%5B%22%E8%87%AA%E5%8A%A8%E4%BA%A7%E7%BA%BF%EF%BC%9A%E6%A8%A1%E6%9D%BF%20%2F%20%E7%94%9F%E6%88%90%20%2F%20%E4%BC%98%E5%8C%96%E5%90%8E%E7%BC%80%22%5D%0A%20%20SCOPE%20--%3E%20HUMAN%5B%22%E4%BA%BA%E5%B7%A5%E4%BA%A7%E7%BA%BF%EF%BC%9A%E5%9F%9F%E4%B8%93%E5%AE%B6%20%2F%20%E4%BC%97%E5%8C%85%22%5D%0A%20%20AUTO%20--%3E%20DEDUP%5B%22%E5%8E%BB%E9%87%8D%E8%81%9A%E7%B1%BB%22%5D%0A%20%20HUMAN%20--%3E%20DEDUP%0A%20%20DEDUP%20--%3E%20MAPP%5B%22%E6%94%BF%E7%AD%96%E6%98%A0%E5%B0%84%22%5D%0A%20%20MAPP%20--%3E%20VALID%5B%22%E6%9C%89%E6%95%88%E5%A4%B1%E8%B4%A5%E4%B8%89%E6%9D%A1%E4%BB%B6%22%5D%0A%20%20VALID%20--%3E%20REG%5B%22%E7%A7%81%E6%9C%89%E5%9B%9E%E5%BD%92%E9%9B%86%22%5D%0A%20%20REG%20--%3E%20RET%5B%22%E4%BF%AE%E5%A4%8D%E5%90%8E%E5%A4%8D%E6%B5%8B%22%5D%0A%20%20RET%20--%3E%20AUTO%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B("h2",{id:"机制",tabindex:"-1"},[E("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=B("p",null,[E("同质化有明确的机制来源：生成器攻击者与被测模型共享大量预训练与指令分布，前者能想到的变体相关地落在后者已被对齐覆盖的邻域里；自动产线的产出彼此也相关，按条数计产出会虚高。"),B("span",{class:"marginnote"},"直觉类比：让同一个出题人连出十套模拟卷，题型和坑长得都一样，考生刷得越多越免疫；人类专家则是换了一套出题思路，专考大纲边缘。这就是「自动化铺广度、人工下深度」的机制根源。"),E("所以度量单位是覆盖矩阵（攻击族 × 政策类别），不是发现条数。人工产线的价值恰好补在分布外：人类的攻击意图跨出语料邻域，是自动生成器抽样不到的模式。")],-1)),(A(),t(i,null,{default:e(()=>[n(l,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20LR%0A%20%20SHARED%5B%22%E5%85%B1%E4%BA%AB%E7%9A%84%E9%A2%84%E8%AE%AD%E7%BB%83%E4%B8%8E%E6%8C%87%E4%BB%A4%E5%88%86%E5%B8%83%22%5D%20---%20ATT%5B%22%E6%94%BB%E5%87%BB%E7%94%9F%E6%88%90%E5%99%A8%22%5D%0A%20%20SHARED%20---%20GEN%5B%22%E8%A2%AB%E6%B5%8B%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20ATT%20--%3E%7C%E6%8A%BD%E6%A0%B7%E5%8F%98%E4%BD%93%7C%20POOL%5B%22%E5%80%99%E9%80%89%E6%94%BB%E5%87%BB%E6%B1%A0%22%5D%0A%20%20POOL%20--%3E%20NEAR%5B%22%E8%90%BD%E5%9C%A8%E5%B7%B2%E8%A2%AB%E5%AF%B9%E9%BD%90%E8%A6%86%E7%9B%96%E7%9A%84%E9%82%BB%E5%9F%9F%22%5D%0A%20%20NEAR%20--%3E%20INFL%5B%22%E6%9D%A1%E6%95%B0%E8%99%9A%E9%AB%98%EF%BC%9A%E5%B9%BF%E5%BA%A6%E7%9A%84%E9%94%99%E8%A7%89%22%5D%0A%20%20HUMAN%5B%22%E4%BA%BA%E5%B7%A5%E6%94%BB%E5%87%BB%E6%84%8F%E5%9B%BE%22%5D%20--%3E%20OOD%5B%22%E8%B7%A8%E5%87%BA%E8%AF%AD%E6%96%99%E9%82%BB%E5%9F%9F%EF%BC%9A%E5%88%86%E5%B8%83%E5%A4%96%22%5D%0A%20%20OOD%20--%3E%20MAT%5B%22%E8%A1%A5%E8%A6%86%E7%9B%96%E7%9F%A9%E9%98%B5%E7%9A%84%E7%A9%BA%E6%A0%BC%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p>回归集必须私有且版本化，这也是机制要求而非保密洁癖：公开的失败题面会变成新的攻击语料，也会变成防御过拟合的目标——修复若只背下了回归集，复测通过就是假阴性。<span class="marginnote">产出度量看矩阵不看条数：一家报五百条重复模板变体，另一家六十条覆盖十二个政策类别、每类至少三个攻击族——后者是更好的红队，尽管条数只有前者的八分之一。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>红队不能证明安全：找不到失败只说明当前产线与预算下没找到，「通过红队」没有操作化的免疫含义，见下一课的鲁棒口径。攻击内容与配方不进公开文档——对外披露只引用聚合指标，这与<a href="/llm/aeval-reporting-standard">评测报告规范</a>的分界一致，此处先立为纪律。人工产线有人的边界：众包疲劳会压低攻击质量，任务轮换与质量抽检要写进协议；测试在沙盒里做，红队成员不接触真实用户数据。最后，有效失败的判定依赖裁判，而对抗输出会同时骗过裁判——判分器的鲁棒性是本课程的后续主题，不是红队课能内部解决的。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>红队的产出是失败在「攻击族 × 政策类别」上的分布，度量看覆盖矩阵不看条数。</li><li>自动化铺广度、人工下深度；生成器攻击的相关性决定了它出不了自己的分布。</li><li>有效失败三条件：政策违反、可复现、判分一致；漏斗把发现变成版本化回归资产。</li><li>回归集私有且版本化：公开即污染，修复背题的复测通过是假阴性。</li><li>范围先行：政策版本与接口清单冻结在先，判定失败才有依据。</li><li>出处：Ganguli et al., 2022；Perez et al., 2022 的模型生成评测谱系；本课程口径。</li></ul>',5))])}const C=s(D,[["render",m]]);export{c as __pageData,C as default};
